def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    prev_bids = []
    aggressive_count = 0
    weak_opp_count = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 2:
                weak_opp_count += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                bid = prev.get('bid', 0.0)
                prev_bids.append(bid)
                if bid >= 140:
                    aggressive_count += 1

    if not alive_opponents:
        return float(min(budget, 18.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    supply_ratio = (supply - MIN_SUPPLY) / float(MAX_SUPPLY - MIN_SUPPLY)
    scarcity = 1.0 - max(0.0, min(1.0, supply_ratio))

    urgency = 0.0
    if hp <= 2:
        urgency += 1.0
    elif hp <= 4:
        urgency += 0.55
    elif hp <= 6:
        urgency += 0.25

    if no_water_days >= 2:
        urgency += 0.9
    elif no_water_days == 1:
        urgency += 0.35

    urgency += scarcity * 0.6

    if highest_prev >= 170:
        pressure_bid = highest_prev * 0.78
    elif highest_prev >= 130:
        pressure_bid = highest_prev * 0.72
    elif highest_prev > 0:
        pressure_bid = max(55.0, highest_prev + 4.0)
    else:
        pressure_bid = 58.0 + 18.0 * scarcity

    base_bid = pressure_bid

    if aggressive_count >= 2 and urgency < 0.8:
        base_bid *= 0.72
    elif aggressive_count >= 1 and urgency < 0.5:
        base_bid *= 0.82

    if weak_opp_count >= 1 and urgency < 0.7:
        base_bid *= 0.92

    if supply >= 22:
        base_bid *= 0.78
    elif supply <= 17:
        base_bid *= 1.12

    if day >= 8 and hp >= 6:
        base_bid *= 0.9

    if urgency >= 1.6:
        bid = max(base_bid, highest_prev + 8.0 if highest_prev > 0 else 95.0)
    elif urgency >= 1.0:
        bid = max(base_bid, avg_prev + 6.0 if avg_prev > 0 else 78.0)
    else:
        bid = base_bid

    reserve_days = max(0, 10 - day)
    soft_cap = budget
    if reserve_days > 0 and hp > 3:
        reserve_target = reserve_days * 22.0
        soft_cap = max(0.0, budget - reserve_target)
        if soft_cap < 18.0:
            soft_cap = min(budget, 18.0 + 6.0 * urgency)

    final_bid = min(budget, bid, max(soft_cap, 0.0) if urgency < 1.2 else budget)

    if hp <= 2 or no_water_days >= 2:
        final_bid = min(budget, max(final_bid, 96.0, highest_prev + 6.0 if highest_prev > 0 else 96.0))

    if final_bid < 0:
        final_bid = 0.0

    return float(round(final_bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    # Alive opponents
    alive = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive.append((opp_id, opp))

    if not alive:
        # If no opponents, spend conservatively
        return float(min(my_status['budget'], DAILY_SALARY * 0.4))

    # Read yesterday bids from previous_trace only
    yesterday_bids = []
    for _, opp in alive:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                yesterday_bids.append(float(prev['bid']))
            except Exception:
                pass

    # Pressure estimate from yesterday: if someone bid extremely high, expect bidding war
    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    # Determine how many water units are likely available today
    # (We don't know exact conversion, but supply range suggests 15..25 total.)
    supply_ratio = 0.0
    if MAX_SUPPLY > MIN_SUPPLY:
        supply_ratio = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    if supply_ratio < 0.0:
        supply_ratio = 0.0
    if supply_ratio > 1.0:
        supply_ratio = 1.0

    # Base bid target: slightly above typical midrange, scaled by supply and our HP
    my_hp = float(my_status.get('hp', 0.0))
    my_budget = float(my_status.get('budget', 0.0))

    # Conservative thresholding around observed bids (roughly 110-145 survivors, Alex died with high bids)
    # If yesterday highest was very high, we avoid extreme overbidding and instead anchor near 115-125.
    if highest_prev_bid >= 170.0:
        target = 120.0 + 10.0 * supply_ratio
    elif highest_prev_bid >= 140.0:
        target = 110.0 + 15.0 * supply_ratio
    else:
        target = 105.0 + 20.0 * supply_ratio

    # If our HP is low, we must secure water more aggressively.
    if my_hp <= 2.0:
        target += 40.0
    elif my_hp <= 4.0:
        target += 20.0

    # If our budget is tight, cap spending.
    # Also incorporate no_water_days to avoid starvation.
    no_water_days = int(my_status.get('no_water_days', 0))
    if no_water_days >= 2:
        target += 15.0

    # Final bid: cannot exceed budget; also keep within a reasonable band to avoid Alex-like overbidding.
    # Use DAILY_SALARY as a soft cap.
    max_reasonable = min(my_budget, DAILY_SALARY * 1.25)
    bid = min(target, max_reasonable)

    # Ensure non-negative
    if bid < 0.0:
        bid = 0.0

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 140
    HP_CRITICAL_THRESHOLD = 3
    base_bid = DAILY_SALARY * 0.65
    if my_status['hp'] <= HP_CRITICAL_THRESHOLD:
        base_bid = DAILY_SALARY * 0.9
    # Ensure we don't bid more than budget
    bid = min(my_status['budget'], base_bid)
    # Keep bid as float; ensure no integer division issues
    return float(bid)
